107	     *  nothing changes. A user who starts watching again is told after those watching meanwhile. */
108	    @Transactional
109	    public Person watch(String sheetId, String user, long id, boolean on) {
110	        Person person = people.findByIdAndSheetId(id, sheetId)
111	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
112	        Optional<PersonWatch> watching = watches.findByPersonIdAndUserName(person.getId(), user);
113	        if (on == watching.isPresent()) return person;
114	        if (on) {
