119	                throw new ResponseStatusException(HttpStatus.CONFLICT, "You already watch this person.");
120	            }
121	        } else {
122	            watches.delete(watching.get());
123	            watches.flush();
124	        }
125	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
126	                + " name=" + person.getName());
