140	    /** Add a person to the sheet with a contact (blank or null: none); refused when another person on
141	     *  the sheet has the same contact. */
142	    @Transactional
143	    public Person add(String sheetId, String user, String name, Grade grade, Integer terms, String contact) {
144	        sheets.load(sheetId);
145	        if (people.existsBySheetIdAndNameKey(sheetId, Person.keyOf(name))
146	                || aliases.existsBySheetIdAndAliasKey(sheetId, Person.keyOf(name))) {
147	            throw nameInUse();
148	        }
149	        String contactKey = Person.contactOf(contact);
150	        if (contactKey != null && people.existsBySheetIdAndContact(sheetId, contactKey)) {
151	            throw contactInUse();
152	        }
153	        Rollup.Snapshot before = rollup.snapshot(sheetId);
154	        Person fresh = new Person(sheetId, name, grade, sheets.today(sheetId));
155	        fresh.setTerms(terms);
156	        fresh.setContact(contactKey);
157	        Person person = save(fresh);
158	        recordChange("PERSON_ADDED", user, person, (terms == null ? "" : " terms=" + terms)
159	                + (contactKey == null ? "" : " contact=" + contactKey));
160	        rollup.recordChanges(user, before);
161	        return person;
162	    }
