164	    /** Change a person's name and give them a grade from a from-date (none: the sheet's today), keeping
165	     *  the grades they were given from other dates; refused when someone has saved the person since
166	     *  the editor loaded this version of them, or when another person on the sheet has the contact
167	     *  given (blank or null: none). */
168	    @Transactional
169	    public Person update(String sheetId, String user, long id, long version, String name, Grade grade,
170	            LocalDate gradeFrom, Integer terms, String contact) {
171	        Person person = people.findByIdAndSheetId(id, sheetId)
172	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
173	        if (person.getVersion() != version) {
174	            throw changedMeanwhile();
175	        }
176	        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.keyOf(name), id)
177	                || aliases.existsBySheetIdAndAliasKey(sheetId, Person.keyOf(name))) {
178	            throw nameInUse();
179	        }
180	        String contactKey = Person.contactOf(contact);
181	        if (contactKey != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contactKey, id)) {
182	            throw contactInUse();
183	        }
184	        Rollup.Snapshot before = rollup.snapshot(sheetId);
185	        boolean contactChanged = !Objects.equals(person.getContact(), contactKey);
186	        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
187	        person.setName(name);
188	        person.setGrade(grade, gradeFrom != null ? gradeFrom : sheets.today(sheetId), sheets.today(sheetId));
189	        person.setTerms(terms);
190	        person.setContact(contactKey);
191	        Person saved = save(person);
192	        recordChange("PERSON_EDITED", user, saved, (termsChanged ? " terms=" + (terms == null ? "" : terms) : "")
193	                + (contactChanged ? " contact=" + (contactKey == null ? "" : contactKey) : ""));
194	        rollup.recordChanges(user, before);
195	        return saved;
196	    }
197	
198	    /** Give a person another name they are found by; refused when blank, or when it equals, as names
199	     *  are compared, any name or alias on the sheet. */
200	    @Transactional
201	    public Person addAlias(String sheetId, String user, long id, String alias) {
202	        Person person = people.findByIdAndSheetId(id, sheetId)
203	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
204	        if (alias == null || alias.isBlank()) {
205	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter an alias.");
206	        }
207	        String key = Person.keyOf(alias);
208	        if (people.existsBySheetIdAndNameKey(sheetId, key) || aliases.existsBySheetIdAndAliasKey(sheetId, key)) {
209	            throw nameInUse();
210	        }
211	        person.addAlias(alias);
212	        Person saved = save(person);
213	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
214	                + " name=" + saved.getName() + " alias=" + alias.trim());
215	        return saved;
216	    }
217	
218	    /** Retire a person from a date, the sheet's today when none is given. Once the sheet's today reaches
219	     *  the date, their open claims count in no live total, unless a statement binds them; their settled
220	     *  claims still count. Claims dated after the date can no longer be added to them. */
221	    @Transactional
222	    public Person retire(String sheetId, String user, long id, LocalDate from) {
223	        Person person = people.findByIdAndSheetId(id, sheetId)
224	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
225	        LocalDate dated = from != null ? from : sheets.today(sheetId);
226	        Rollup.Snapshot before = rollup.snapshot(sheetId);
227	        person.setRetiredFrom(dated, sheets.today(sheetId));
228	        Person saved = save(person);
229	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
230	                + " name=" + saved.getName() + " from=" + dated);
231	        rollup.recordChanges(user, before);
232	        return saved;
233	    }
234	
235	    /** Put a hold on a person from a date (none: the sheet's today) to a date (none: no end); refused
236	     *  when it ends before it starts. Their open claims dated within it count in no live total, unless
237	     *  a statement binds them; their settled claims still count. */
238	    @Transactional
239	    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
240	        Person person = people.findByIdAndSheetId(id, sheetId)
241	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
242	        LocalDate dated = from != null ? from : sheets.today(sheetId);
243	        if (to != null && to.isBefore(dated)) {
244	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
245	        }
246	        Rollup.Snapshot before = rollup.snapshot(sheetId);
247	        person.hold(dated, to, sheets.today(sheetId));
248	        Person saved = save(person);
249	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
250	                + " from=" + dated);
251	        rollup.recordChanges(user, before);
252	        return saved;
253	    }
254	
255	    /** The person's audit line, with the grade in force on the sheet's today, then the fields given. */
256	    private void recordChange(String event, String user, Person person, String fields) {
257	        audit.recordOnCommit(event + " sheet=" + person.getSheetId() + " by=" + user
258	                + " name=" + person.getName() + " grade=" + person.gradeOn(sheets.today(person.getSheetId()))
259	                + fields);
260	    }
261	
262	    private Person save(Person person) {
263	        try {
264	            return people.saveAndFlush(person);
265	        } catch (OptimisticLockingFailureException raced) {
266	            // Another user saved the same person at the same moment.
267	            throw changedMeanwhile();
268	        } catch (DataIntegrityViolationException raced) {
269	            // Another user took the same name, or the same contact, at the same moment.
270	            String cause = String.valueOf(raced.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
271	            throw cause.contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
272	        }
273	    }
274	
275	    private static ResponseStatusException changedMeanwhile() {
276	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
277	                "Someone else has saved this person since it was opened.");
278	    }
279	
280	    private static ResponseStatusException contactInUse() {
281	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the sheet.");
282	    }
283	
284	    private static ResponseStatusException nameInUse() {
285	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on the sheet.");
286	    }
287	}
